import random, itertools
from netsim.sdn_controller import SDNController

def floyd(graph, nodes):
    INF=float('inf')
    d={u:{v:(0 if u==v else INF) for v in nodes} for u in nodes}
    for u in graph:
        for v,w in graph[u].items():
            d[u][v]=min(d[u][v],w)
    for k in nodes:
        for i in nodes:
            for j in nodes:
                if d[i][k]+d[k][j]<d[i][j]: d[i][j]=d[i][k]+d[k][j]
    return d

