import random, itertools
from netsim.sdn_controller import *
from netsim.net import Mininet
from netsim.topo import LinearTopo, RingTopo, TreeTopo, SingleSwitchTopo

def check(net, c, tag):
    prob=[]
    # 1. every rule maps to an installed path
    for name,tbl in c.flow_tables.items():
        for r in tbl.rules:
            key=(r.match_fields.get("src_ip"), r.match_fields.get("dst_ip"))
            if key not in c.installed_paths:
                prob.append(("orphan", tag, name, key))
            else:
                if name not in c.installed_paths[key]:
                    prob.append(("rule-on-offpath-switch", tag, name, key, c.installed_paths[key]))
    # 2. every installed path has rules on every switch, with right port
    for key,path in c.installed_paths.items():
        for i,n in enumerate(path):
            if n not in c.flow_tables: continue
            r=c.flow_tables[n].lookup({"src_ip":key[0],"dst_ip":key[1]})
            if r is None:
                prob.append(("missing-rule", tag, n, key, path)); continue
            nh = path[i+1] if i+1<len(path) else None
            want = net[n].portTo(nh) if nh else None
            got = r.actions[0].get("port")
            if want!=got:
                prob.append(("bad-port", tag, n, key, path, want, got))
        # 3. path must be valid in current graph
        for u,v in zip(path,path[1:]):
            if v not in c.graph.get(u,{}):
                prob.append(("path-uses-dead-link", tag, key, path, (u,v)))
    return prob

random.seed(3)
allprob=[]
for trial in range(60):
    kind=random.choice(["ring","linear","tree","single"])
    if kind=="ring": topo=RingTopo(k=random.randint(3,6), n=random.randint(1,2))
    elif kind=="linear": topo=LinearTopo(k=random.randint(2,5), n=random.randint(1,2))
